	@Test
	void graphJoinReadsMatchingQuadsThroughNativeRestrictions() {
		SailRepository repository = repository(GraphRestrictionMode.REQUIRE_RESTRICTED, true);
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var graph = vf.createIRI("urn:restriction:graph");
			var predicate = vf.createIRI("urn:restriction:p");
			var object = vf.createIRI("urn:restriction:o");
			connection.begin();
			for (int i = 0; i < 10_000; i++) {
				connection.add(vf.createIRI("urn:restriction:s" + i), predicate, object, graph);
			}
			connection.commit();
			var query = connection.prepareTupleQuery("""
					SELECT ?s ?o ?g {
					  VALUES ?s { <urn:restriction:s3> <urn:restriction:s3> <urn:restriction:s91> }
					  GRAPH ?g { ?s <urn:restriction:p> ?o }
					}
					""");
			List<BindingSet> rows = rows(query);
			assertThat(rows).extracting(row -> row.getValue("s"))
					.containsExactlyInAnyOrder(
							vf.createIRI("urn:restriction:s3"), vf.createIRI("urn:restriction:s3"),
							vf.createIRI("urn:restriction:s91"));
			assertThat(rows).allSatisfy(row -> {
				assertThat(row.getValue("g")).isEqualTo(graph);
				assertThat(row.getValue("o")).isEqualTo(object);
			});
			GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			assertThat(actualMetric(plan, NativeGraphRestrictionBody.STATEMENT_ROWS))
					.as("quad rows read by the native restriction path, one per distinct VALUES key")
					.isEqualTo(2L);
			assertThat(actualMetric(plan, NativeGraphRestrictionBody.SOURCE_OPENS)).isEqualTo(2L);
			assertThat(actualMetric(plan, NativeGraphRestrictionBody.SUBJECT_CONTEXT_OPENS)).isEqualTo(2L);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void onlyAssuredDictionaryMissesSkipTheNativeStatementAccess() {
		SailRepository repository = repository(GraphRestrictionMode.REQUIRE_RESTRICTED, true);
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var graph = vf.createIRI("urn:g");
			var p = vf.createIRI("urn:p");
			var o = vf.createLiteral(7);
			connection.add(vf.createIRI("urn:match"), p, o, graph);
			connection.add(vf.createIRI("urn:known"), vf.createIRI("urn:irrelevant"), o, graph);
			var query = connection.prepareTupleQuery("""
					SELECT ?s ?g ?o {
					  VALUES ?s { <urn:absent> <urn:known> 7 }
					  GRAPH ?g { ?s <urn:p> ?o }
					}
					""");
			assertThat(rows(query)).isEmpty();
			GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			assertThat(actualMetric(plan, NativeGraphRestrictionBody.DICTIONARY_MISSES)).isEqualTo(1L);
			assertThat(actualMetric(plan, NativeGraphRestrictionBody.SOURCE_OPENS)).isEqualTo(1L);
			assertThat(actualMetric(plan, NativeGraphRestrictionBody.STATEMENT_ROWS)).isZero();
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void fixedAndEnumeratedNilUseDifferentPhysicalGraphs() {
		String fixed = """
				SELECT ?s ?o {
				  VALUES ?s { <urn:default> <urn:named> }
				  GRAPH <%s> { ?s <urn:p> ?o }
				}
				""".formatted(RDF4J.NIL);
		String enumerated = """
				SELECT ?s ?o ?g {
				  VALUES (?s ?g) { (<urn:default> <%s>) (<urn:named> <%s>) }
				  GRAPH ?g { ?s <urn:p> ?o }
				}
				""".formatted(RDF4J.NIL, RDF4J.NIL);
		SailRepository repository = repository(GraphRestrictionMode.REQUIRE_RESTRICTED, true);
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var p = vf.createIRI("urn:p");
			var o = vf.createIRI("urn:o");
			connection.add(vf.createIRI("urn:default"), p, o);
			connection.add(vf.createIRI("urn:named"), p, o, RDF4J.NIL);
			var fixedQuery = connection.prepareTupleQuery(fixed);
			var enumeratedQuery = connection.prepareTupleQuery(enumerated);
			assertThat(rows(fixedQuery)).extracting(row -> row.getValue("s"))
					.containsExactly(vf.createIRI("urn:default"));
			assertThat(rows(enumeratedQuery)).extracting(row -> row.getValue("s"))
					.containsExactly(vf.createIRI("urn:named"));
			for (var query : List.of(fixedQuery, enumeratedQuery)) {
				assertThat(actualMetric(query.explain(Explanation.Level.Telemetry).toGenericPlanNode(),
						NativeGraphRestrictionBody.STATEMENT_ROWS)).isEqualTo(1L);
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void connectedProbesPreserveRepeatedBindingsAndNamedDataset() {
		String sparql = """
				SELECT ?s ?o ?g {
				  VALUES (?s ?o) { (<urn:s> UNDEF) (<urn:s> <urn:x>) (UNDEF <urn:other>) }
				  GRAPH ?g { ?s <urn:p> ?o . ?o <urn:q> ?o }
				}
				""";
		SimpleDataset dataset = new SimpleDataset();
		SailRepository repository = repository(GraphRestrictionMode.REQUIRE_RESTRICTED, true);
		List<BindingSet> restricted;
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var graph = vf.createBNode("restriction-graph");
			var s = vf.createIRI("urn:s");
			var p = vf.createIRI("urn:p");
			var q = vf.createIRI("urn:q");
			var x = vf.createIRI("urn:x");
			var other = vf.createIRI("urn:other");
			connection.add(s, p, x, graph);
			connection.add(x, q, x, graph);
			connection.add(s, p, other, graph);
			connection.add(other, q, x, graph);
			connection.add(other, q, other, vf.createIRI("urn:excluded"));
			dataset.addNamedGraph(graph);
			var query = connection.prepareTupleQuery(sparql);
			query.setDataset(dataset);
			restricted = rows(query);
			assertThat(restricted).hasSize(2).allSatisfy(row -> {
				assertThat(row.getValue("s")).isEqualTo(s);
				assertThat(row.getValue("o")).isEqualTo(x);
				assertThat(row.getValue("g")).isEqualTo(graph);
			});
			assertThat(actualMetric(query.explain(Explanation.Level.Telemetry).toGenericPlanNode(),
					NativeGraphRestrictionBody.SOURCE_OPENS)).isPositive();
		} finally {
			repository.shutDown();
		}
		for (boolean nativeEnabled : new boolean[] { false, true }) {
			SailRepository independent = repository(GraphRestrictionMode.FORCE_INDEPENDENT, nativeEnabled);
			try (var connection = independent.getConnection()) {
				var query = connection.prepareTupleQuery(sparql);
				query.setDataset(dataset);
				assertThat(rows(query)).containsExactlyInAnyOrderElementsOf(restricted);
			} finally {
				independent.shutDown();
			}
		}
	}

	@Test
	@Timeout(30)
	void laterProbeUsesTheOriginalSnapshotAndEmptyDatasetDoesNotOpenAScan() {
		SailRepository repository = repository(GraphRestrictionMode.REQUIRE_RESTRICTED, true);
		try (var reader = repository.getConnection(); var writer = repository.getConnection()) {
			var vf = reader.getValueFactory();
			var graph = vf.createIRI("urn:graph");
			var p = vf.createIRI("urn:p");
			var o = vf.createIRI("urn:o");
			var first = vf.createIRI("urn:first");
			var later = vf.createIRI("urn:later");
			writer.add(first, p, o, graph);
			var query = reader.prepareTupleQuery("""
					SELECT ?s ?g {
					  VALUES ?s { <urn:first> <urn:later> }
					  GRAPH ?g { ?s <urn:p> ?o }
					}
					""");
			try (var result = query.evaluate()) {
				assertThat(result.hasNext()).isTrue();
				assertThat(result.next().getValue("s")).isEqualTo(first);
				writer.add(later, p, o, graph);
				assertThat(result.hasNext()).isFalse();
			}
			assertThat(rows(query)).extracting(row -> row.getValue("s")).containsExactlyInAnyOrder(first, later);
			SimpleDataset empty = new SimpleDataset();
			empty.setExplicitReadDataset(true);
			query.setDataset(empty);
			assertThat(rows(query)).isEmpty();
			assertThat(actualMetric(query.explain(Explanation.Level.Telemetry).toGenericPlanNode(),
					NativeGraphRestrictionBody.SOURCE_OPENS)).isNull();
		} finally {
			repository.shutDown();
		}
	}

