	@Test
	void automaticPolicyKeepsTheNativeIndependentJoinWhenBroadMasksRejectProbes() {
		SailRepository repository = repository(GraphRestrictionMode.AUTO, true);
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var graph = vf.createIRI("urn:g");
			var predicate = vf.createIRI("urn:p");
			var first = vf.createIRI("urn:s0");
			int statements = 6_000;
			connection.begin();
			for (int index = 0; index < statements; index++) {
				connection.add(vf.createIRI("urn:s" + index), predicate, graph, graph);
			}
			connection.commit();
			// The unrestricted graph does not fit the bounded frame cache. Each UNDEF occurrence multiplies its bag.
			var query = connection.prepareTupleQuery("""
					SELECT ?s ?g {
					  VALUES ?s { UNDEF <urn:s0> UNDEF UNDEF }
					  GRAPH ?g { ?s <urn:p> ?g }
					}
					""");
			List<BindingSet> rows = rows(query);
			assertThat(rows).hasSize(3 * statements + 1)
					.allSatisfy(row -> assertThat(row.getValue("g")).isEqualTo(graph));
			assertThat(rows.stream().filter(row -> first.equals(row.getValue("s"))).count()).isEqualTo(4L);
			GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			assertThat(plan.getStringMetricPlanned("plannedExecutionEngine"))
					.as("cost refusal retains the original native independent join")
					.isEqualTo("lmdb-native");
			assertThat(actualMetric(plan, NativeGraphRestrictionBody.PROBES)).isNull();
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void automaticPolicyStillProbesWhenTheBroadFrameFitsTheResultCache() {
		SailRepository repository = repository(GraphRestrictionMode.AUTO, true);
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			var graph = vf.createIRI("urn:g");
			var predicate = vf.createIRI("urn:p");
			for (int index = 0; index < 8; index++) {
				connection.add(vf.createIRI("urn:s" + index), predicate, graph, graph);
			}
			var query = connection.prepareTupleQuery("""
					SELECT ?s ?g {
					  VALUES ?s { UNDEF <urn:s0> UNDEF UNDEF }
					  GRAPH ?g { ?s <urn:p> ?g }
					}
					""");
			assertThat(rows(query)).hasSize(25);
			GenericPlanNode plan = query.explain(Explanation.Level.Telemetry).toGenericPlanNode();
			assertThat(actualMetric(plan, NativeGraphRestrictionBody.SOURCE_OPENS))
					.as("one graph-wide open shared by the UNDEF occurrences and one subject/context seek")
					.isEqualTo(2L);
			assertThat(actualMetric(plan, NativeGraphRestrictionBody.SUBJECT_CONTEXT_OPENS))
					.as("one native seek for the complete key beside the reusable broad frame")
					.isEqualTo(1L);
			assertThat(actualMetric(plan, "graphRestrictionCacheHits")).isEqualTo(2L);
		} finally {
			repository.shutDown();
		}
	}

