	private SailRepository repository(GraphRestrictionMode mode, boolean nativeEnabled) {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(nativeEnabled)
				.setSketchEstimatorEnabled(false));
		store.setQueryExecutionPolicy(QueryExecutionPolicy.EXPERIMENTAL.withGraphRestrictionMode(mode));
		return new SailRepository(store);
	}

	private static List<BindingSet> rows(TupleQuery query) {
		List<BindingSet> rows = new ArrayList<>();
		try (var result = query.evaluate()) {
			result.forEachRemaining(rows::add);
		}
		return rows;
	}

	private static Long actualMetric(GenericPlanNode node, String name) {
		Long value = node.getLongMetricActual(name);
		if (value != null || node.getPlans() == null) {
			return value;
		}
		for (GenericPlanNode child : node.getPlans()) {
			Long childValue = actualMetric(child, name);
			if (childValue != null) {
				return childValue;
			}
		}
		return null;
	}
